using Npgsql;
using Modules.Catalog.Services;
using Modules.Catalog.DTOs;
using Modules.Catalog.Entities;
using Core.Transactions;
using Shared.Primitives.Identifiers;
using Xunit;

namespace CatalogTests;

public sealed class CatalogDatabaseTests
{
    [Fact]
    public async Task RuntimeRoleCannotReadAnotherTenantCatalog()
    {
        var adminConnectionString = Environment.GetEnvironmentVariable("TODIR_CATALOG_ADMIN_CONNECTION"); var runtimeConnectionString = Environment.GetEnvironmentVariable("TODIR_CATALOG_RUNTIME_CONNECTION"); if (string.IsNullOrWhiteSpace(adminConnectionString) || string.IsNullOrWhiteSpace(runtimeConnectionString)) return;
        await ResetRuntimePasswordAsync(adminConnectionString); var tenantA = Guid.CreateVersion7(); var tenantB = Guid.CreateVersion7();
        await using (var admin = NpgsqlDataSource.Create(adminConnectionString)) await using (var connection = await admin.OpenConnectionAsync()) { await using var command = new NpgsqlCommand("insert into platform_tenancy.tenant (id,slug,display_name,status,created_at,version) values ($1,$2,$3,'Active',now(),1),($4,$5,$6,'Active',now(),1)", connection); command.Parameters.AddWithValue(tenantA); command.Parameters.AddWithValue($"catalog-a-{tenantA:N}"); command.Parameters.AddWithValue("Catalog A"); command.Parameters.AddWithValue(tenantB); command.Parameters.AddWithValue($"catalog-b-{tenantB:N}"); command.Parameters.AddWithValue("Catalog B"); await command.ExecuteNonQueryAsync(); }
        try { await using var runtime = NpgsqlDataSource.Create(runtimeConnectionString); await using var connection = await runtime.OpenConnectionAsync(); await using var transaction = await connection.BeginTransactionAsync(); await using (var context = new NpgsqlCommand("select set_config('app.tenant_id',$1,true)", connection, transaction)) { context.Parameters.AddWithValue(tenantA.ToString("D")); await context.ExecuteNonQueryAsync(); } var id = Guid.CreateVersion7(); await using (var insert = new NpgsqlCommand("insert into foundation_catalog.brand (tenant_id,id,name,name_normalized,status,created_at,updated_at,version) values ($1,$2,'A','a','Active',now(),now(),1)", connection, transaction)) { insert.Parameters.AddWithValue(tenantA); insert.Parameters.AddWithValue(id); await insert.ExecuteNonQueryAsync(); } await using (var switchTenant = new NpgsqlCommand("select set_config('app.tenant_id',$1,true)", connection, transaction)) { switchTenant.Parameters.AddWithValue(tenantB.ToString("D")); await switchTenant.ExecuteNonQueryAsync(); } await using var select = new NpgsqlCommand("select count(*) from foundation_catalog.brand", connection, transaction); Assert.Equal(0L, (long)(await select.ExecuteScalarAsync() ?? -1L)); await transaction.RollbackAsync(); }
        finally { await using var admin = NpgsqlDataSource.Create(adminConnectionString); await using var connection = await admin.OpenConnectionAsync(); foreach (var sql in new[] { "delete from foundation_catalog.brand where tenant_id in ($1,$2)", "delete from platform_tenancy.tenant where id in ($1,$2)" }) { await using var cleanup = new NpgsqlCommand(sql, connection); cleanup.Parameters.AddWithValue(tenantA); cleanup.Parameters.AddWithValue(tenantB); await cleanup.ExecuteNonQueryAsync(); } }
    }

    [Fact]
    public async Task ProductServiceCreatesServiceWithDefaultVariantAndBaseUom()
    {
        var adminConnectionString = Environment.GetEnvironmentVariable("TODIR_CATALOG_ADMIN_CONNECTION"); var runtimeConnectionString = Environment.GetEnvironmentVariable("TODIR_CATALOG_RUNTIME_CONNECTION"); if (string.IsNullOrWhiteSpace(adminConnectionString) || string.IsNullOrWhiteSpace(runtimeConnectionString)) return;
        await ResetRuntimePasswordAsync(adminConnectionString); var tenant = Guid.CreateVersion7(); var actor = Guid.CreateVersion7(); var membership = Guid.CreateVersion7(); var uom = Guid.CreateVersion7(); var alternateUom = Guid.CreateVersion7();
        await using (var admin = NpgsqlDataSource.Create(adminConnectionString)) await using (var connection = await admin.OpenConnectionAsync()) { await using var command = new NpgsqlCommand("insert into platform_tenancy.tenant (id,slug,display_name,status,created_at,version) values ($1,$2,$3,'Active',now(),1)", connection); command.Parameters.AddWithValue(tenant); command.Parameters.AddWithValue($"catalog-service-{tenant:N}"); command.Parameters.AddWithValue("Catalog Service"); await command.ExecuteNonQueryAsync(); }
        try { await using var dataSource = NpgsqlDataSource.Create(runtimeConnectionString); await using (var connection = await dataSource.OpenConnectionAsync()) { await using (var context = new NpgsqlCommand("select set_config('app.tenant_id',$1,false)", connection)) { context.Parameters.AddWithValue(tenant.ToString("D")); await context.ExecuteNonQueryAsync(); } await using var insert = new NpgsqlCommand("insert into foundation_catalog.uom (tenant_id,id,code,name_ar,name_en,dimension,allow_fraction,precision,status,created_at,updated_at,version) values ($1,$2,'HOUR','ساعة','Hour','Time',true,2,'Active',now(),now(),1),($1,$3,'DAY','يوم','Day','Time',true,2,'Active',now(),now(),1)", connection); insert.Parameters.AddWithValue(tenant); insert.Parameters.AddWithValue(uom); insert.Parameters.AddWithValue(alternateUom); await insert.ExecuteNonQueryAsync(); }
            var service = new ProductService(new NpgsqlTransactionCoordinator(dataSource), dataSource); var created = await service.CreateAsync(new TenantId(tenant), actor, membership, new CreateProductRequest("استشارة", ProductNature.Service, "CONSULT-01", "استشارة", "Consulting", null, null, uom), Guid.CreateVersion7(), null, CancellationToken.None); Assert.Equal(ProductNature.Service, created.Nature); Assert.Equal("CONSULT-01", created.Sku); Assert.Equal("HOUR", created.BaseUomCode); Assert.NotEqual(Guid.Empty, created.DefaultVariantId); var details = new CatalogDetailService(new NpgsqlTransactionCoordinator(dataSource), dataSource); var conversion = await details.AddUomAsync(new TenantId(tenant), created.Id, created.DefaultVariantId, new AddProductUomRequest(alternateUom, 8m, DateTimeOffset.UtcNow), CancellationToken.None); Assert.Equal(8m, conversion.FactorToBase); var barcode = await service.AddBarcodeAsync(new TenantId(tenant), actor, membership, created.Id, null, new AddBarcodeRequest(null, BarcodeType.Ean13, "1234567890123", true), Guid.CreateVersion7(), CancellationToken.None); Assert.Equal(created.DefaultVariantId, barcode.VariantId); await details.AddAliasAsync(new TenantId(tenant), created.Id, new AddAliasRequest(created.DefaultVariantId, "Consulting Alias", "Internal", "en"), CancellationToken.None); var snapshot = await details.ResolveAsync(new TenantId(tenant), "CONSULT-01", CancellationToken.None); Assert.Equal(created.DefaultVariantId, snapshot.VariantId); var barcodeSnapshot = await details.ResolveAsync(new TenantId(tenant), "1234567890123", CancellationToken.None); Assert.Equal(created.DefaultVariantId, barcodeSnapshot.VariantId); var search = await service.ListAsync(new TenantId(tenant), "1234567890123", null, null, null, null, 1, 25, CancellationToken.None); Assert.Contains(search.Items, item => item.Id == created.Id); var readiness = await details.ReadinessAsync(new TenantId(tenant), created.Id, CancellationToken.None); Assert.True(readiness.Ready); }
        finally { await using var admin = NpgsqlDataSource.Create(adminConnectionString); await using var connection = await admin.OpenConnectionAsync(); foreach (var sql in new[] { "delete from foundation_catalog.product_alias where tenant_id=$1", "delete from foundation_catalog.product_barcode where tenant_id=$1", "delete from foundation_catalog.catalog_search_projection where tenant_id=$1", "delete from foundation_catalog.product_uom where tenant_id=$1", "delete from foundation_catalog.product_visibility where tenant_id=$1", "delete from foundation_catalog.product_variant where tenant_id=$1", "delete from foundation_catalog.product_template where tenant_id=$1", "delete from foundation_catalog.uom where tenant_id=$1", "delete from platform_messaging.outbox_message where tenant_id=$1", "delete from platform_audit.audit_entry where tenant_id=$1", "delete from platform_tenancy.tenant where id=$1" }) { await using var cleanup = new NpgsqlCommand(sql, connection); cleanup.Parameters.AddWithValue(tenant); await cleanup.ExecuteNonQueryAsync(); } }
    }

    private static async Task ResetRuntimePasswordAsync(string adminConnectionString) { await using var admin = NpgsqlDataSource.Create(adminConnectionString); await using var connection = await admin.OpenConnectionAsync(); await using var command = new NpgsqlCommand("alter role erp_app password 'todir-app-dev'", connection); await command.ExecuteNonQueryAsync(); }
}
